/* join-match-board 엔진 — 두 표(왼쪽=명세 행 · 오른쪽=마스터)를 ON 조건으로 짝지어 INNER JOIN 결과를 보여 준다.
   오른쪽(마스터) 행을 숨겨 가며 "짝 없는 왼쪽 행은 INNER에서 빠진다"를 확인. sy-subrc/sy-dbcnt 표시.
   골격 계약: #jmbLeft · #jmbRight · .jmb-hide(칩 호스트) · #jmbBody · #jmbCnt.
   config: window.JMB_CFG = { joinKey, keyLabel, leftNoun, rightNoun, unit,
            left:{ rows:[..], fields:[{key,label,name}] }, right:{ rows:[..], fields:[..] },
            resultCols:[{key, from:'left'|'right', l}] }. 높이: _autoheight.js. */
(function () {
  var CFG = window.JMB_CFG || {};
  var L = CFG.left || { rows: [], fields: [] };
  var R = CFG.right || { rows: [], fields: [] };
  var KEY = CFG.joinKey;                  // 조인 키 필드명(양쪽 공통)
  var KLB = CFG.keyLabel || KEY;          // 카드 키 칩에 붙일 라벨
  var UNIT = CFG.unit || '행';
  var SLOTS = ['k10', 'k20', 'k30'];      // 엔진 CSS의 색 슬롯 — 키 값 등장 순서대로 배정
  var hidden = {};   // 키 값 -> true(숨김)
  var leftEl = document.getElementById('jmbLeft');
  var rightEl = document.getElementById('jmbRight');
  var hideEl = document.querySelector('.jmb-hide');
  var bodyEl = document.getElementById('jmbBody');
  var cntEl = document.getElementById('jmbCnt');

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }

  var colorMap = {};
  (function () {
    var n = 0;
    L.rows.concat(R.rows).forEach(function (r) {
      if (!(r[KEY] in colorMap)) { colorMap[r[KEY]] = SLOTS[n] || 'knone'; n++; }
    });
  })();
  function dotClass(v) { return colorMap[v] || 'knone'; }
  function matchOf(v) {
    return R.rows.filter(function (r) { return !hidden[r[KEY]]; })
      .find(function (r) { return r[KEY] === v; });
  }

  function fieldsHtml(row, fields) {
    return (fields || []).map(function (f) {
      var txt = (f.label ? esc(f.label) + ' ' : '') + esc(row[f.key]);
      return '<span class="' + (f.name ? 'nm' : '') + '">' + txt + '</span>';
    }).join('');
  }
  function keyHtml(v) {
    return '<span class="jmb-key"><span class="jmb-dot ' + dotClass(v) + '"></span>' + esc(KLB) + ' ' + esc(v) + '</span>';
  }

  function renderCards() {
    leftEl.innerHTML = L.rows.map(function (r) {
      return '<div class="jmb-card">' + fieldsHtml(r, L.fields) + keyHtml(r[KEY]) + '</div>';
    }).join('');
    rightEl.innerHTML = R.rows.map(function (r) {
      return '<div class="jmb-card' + (hidden[r[KEY]] ? ' dim' : '') + '">' + keyHtml(r[KEY]) + fieldsHtml(r, R.fields) + '</div>';
    }).join('');
  }

  function renderResult() {
    var keep = 0;
    bodyEl.innerHTML = L.rows.map(function (r) {
      var m = matchOf(r[KEY]);
      if (m) keep++;
      var tds = (CFG.resultCols || []).map(function (c) {
        var v = (c.from === 'right') ? (m ? m[c.key] : '—') : r[c.key];
        return '<td class="' + (c.l ? 'l' : '') + '">' + esc(v) + '</td>';
      }).join('');
      var badge = m ? '<span class="badge-keep">매칭 ✔</span>' : '<span class="badge-drop">INNER 제외</span>';
      return '<tr class="' + (m ? 'keep' : 'drop') + '">' + tds + '<td>' + badge + '</td></tr>';
    }).join('');
    var subrc = keep > 0 ? 0 : 4;
    cntEl.innerHTML = 'INNER JOIN 결과 = <b>' + keep + '행</b> &nbsp;(' + esc(CFG.leftNoun || '왼쪽') + ' ' +
      L.rows.length + UNIT + ' 중 ' + keep + UNIT + ' 매칭) &nbsp;·&nbsp; sy-dbcnt = ' + keep + ' &nbsp;·&nbsp; sy-subrc = ' + subrc;
  }

  function renderHideChips() {
    var lbl = (R.fields && R.fields[0]) ? R.fields[0].key : null;
    hideEl.innerHTML = R.rows.map(function (r) {
      var nm = lbl ? '(' + esc(r[lbl]) + ')' : '';
      return '<button class="jmb-chip" type="button" data-k="' + esc(r[KEY]) + '" aria-pressed="false">' +
        esc(CFG.rightNoun || '') + ' ' + esc(r[KEY]) + nm + ' 숨김</button>';
    }).join('');
  }

  if (hideEl) hideEl.addEventListener('click', function (e) {
    var chip = e.target.closest('.jmb-chip'); if (!chip) return;
    var k = chip.getAttribute('data-k');
    hidden[k] = !hidden[k];
    chip.setAttribute('aria-pressed', hidden[k] ? 'true' : 'false');
    renderCards(); renderResult();
  });

  renderHideChips();
  renderCards();
  renderResult();
})();

FILE: C:\SAP\sap-dev-academy\embeds\_engine\outer-join-switch.js
/* outer-join-switch 엔진 — INNER↔LEFT OUTER 토글로 기준 행 보존 차이를 보고, WHERE 오른쪽필터 함정을 확인.
   골격 계약: [data-mode="INNER"]/[data-mode="LEFT"] · [data-where] · #ojsBody · #ojsCheck · #ojsSql.
   config: window.OJS_CFG = { concerts:[{concert_id,artist}], bookings:[{booking_id,concert_id,seats,status}], whereField, whereVal }.
   높이: _autoheight.js. */
(function () {
  var CFG = window.OJS_CFG || { concerts: [], bookings: [], whereField: 'status', whereVal: 'N' };
  var mode = 'LEFT';
  var whereOn = false;
  var bodyEl = document.getElementById('ojsBody');
  var checkEl = document.getElementById('ojsCheck');
  var sqlEl = document.getElementById('ojsSql');
  var modeBtns = Array.prototype.slice.call(document.querySelectorAll('[data-mode]'));
  var whereBtn = document.querySelector('[data-where]');

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }

  function buildRows() {
    var rows = [];
    CFG.concerts.forEach(function (c) {
      var ms = CFG.bookings.filter(function (b) { return b.concert_id === c.concert_id; });
      if (ms.length) ms.forEach(function (b) {
        rows.push({ concert_id: c.concert_id, artist: c.artist, booking_id: b.booking_id, seats: b.seats, status: b.status, kind: 'match' });
      });
      else if (mode === 'LEFT') rows.push({ concert_id: c.concert_id, artist: c.artist, booking_id: '', seats: '', status: '', kind: 'left' });
    });
    if (whereOn) rows = rows.filter(function (r) { return r[CFG.whereField] === CFG.whereVal; });  // WHERE는 오른쪽 필드를 최종 결과에서 거른다
    return rows;
  }

  function renderSql() {
    var lj = mode === 'LEFT' ? '<span class="lj">LEFT OUTER JOIN</span>' : '<span class="kw">INNER JOIN</span>';
    var where = whereOn ? '\n  <span class="wh">WHERE</span> b~' + CFG.whereField + " = '" + CFG.whereVal + "'" : '';
    sqlEl.innerHTML =
      '<span class="kw">SELECT</span> c~concert_id c~artist b~booking_id b~seats\n' +
      '  <span class="kw">FROM</span> zconcert <span class="kw">AS</span> c\n' +
      '  ' + lj + ' zbooking <span class="kw">AS</span> b\n' +
      '    <span class="kw">ON</span> c~concert_id = b~concert_id' + where + '.';
  }

  function renderTable(rows) {
    bodyEl.innerHTML = rows.map(function (r) {
      var initCls = r.kind === 'left' ? ' init' : '';
      var bid = r.booking_id === '' ? '<span class="init">—</span>' : esc(r.booking_id);
      var seats = r.seats === '' ? '<span class="init">—</span>' : esc(r.seats);
      var reason = r.kind === 'left' ? 'LEFT 보존 (오른쪽 초기값)' : '매칭';
      return '<tr class="' + (r.kind === 'left' ? 'left' : '') + '">' +
        '<td>' + esc(r.concert_id) + '</td><td class="l">' + esc(r.artist) + '</td>' +
        '<td class="' + initCls.trim() + '">' + bid + '</td><td class="' + initCls.trim() + '">' + seats + '</td>' +
        '<td class="ojs-reason">' + reason + '</td></tr>';
    }).join('');
  }

  function renderCheck(rows) {
    var present = {};
    rows.forEach(function (r) { present[r.concert_id] = true; });
    var all = CFG.concerts.map(function (c) { return c.concert_id; });
    var missing = all.filter(function (id) { return !present[id]; });
    var c003 = all[all.length - 1];
    checkEl.className = 'ojs-check';
    if (mode === 'LEFT' && whereOn && missing.indexOf(c003) >= 0) {
      checkEl.classList.add('warn');
      checkEl.innerHTML = '⚠️ <b>LEFT인데도 ' + c003 + '이(가) 빠졌습니다.</b> WHERE <b>b~' + CFG.whereField + "='" + CFG.whereVal + "'</b>가 예매 없는 공연의 오른쪽 초기값(빈 " + CFG.whereField + ')을 걸러냈기 때문입니다. 오른쪽 조건은 ON에 두는 편이 안전합니다.';
    } else if (mode === 'LEFT') {
      checkEl.classList.add('ok');
      checkEl.innerHTML = '✅ <b>' + c003 + '도 결과에 남았습니다</b> — 왼쪽(기준) 공연을 보존했습니다. 오른쪽 값은 초기값(—)으로 보입니다.';
    } else {
      checkEl.innerHTML = 'ℹ️ INNER JOIN — 예매가 없는 ' + (missing.length ? missing.join(', ') : '공연') + '은(는) 짝이 없어 결과에서 빠집니다.';
    }
  }

  function render() {
    modeBtns.forEach(function (b) { b.setAttribute('aria-pressed', b.getAttribute('data-mode') === mode ? 'true' : 'false'); });
    if (whereBtn) whereBtn.setAttribute('aria-pressed', whereOn ? 'true' : 'false');
    var rows = buildRows();
    renderSql(); renderTable(rows); renderCheck(rows);
  }

  modeBtns.forEach(function (b) { b.addEventListener('click', function () { mode = b.getAttribute('data-mode'); render(); }); });
  if (whereBtn) whereBtn.addEventListener('click', function () { whereOn = !whereOn; render(); });

  render();
})();

FILE: C:\SAP\sap-dev-academy\embeds\_engine\group-by-lab.js
/* group-by-lab 엔진 — 그룹 키와 모드(GROUP BY / DISTINCT)를 바꿔 원본 행을 요약하고 색으로 묶는다.
   골격 계약: .gbl-keys(세그) · .gbl-mode(세그) · #gblSrc(원본 tbody) · #gblRes · #gblNote.
   config: window.GBL_CFG = { rows:[..], cols:[{key,label,num}], groupOptions:[{label,keys:[..]}], sumField }.
   높이: _autoheight.js. */
(function () {
  var CFG = window.GBL_CFG || { rows: [], cols: [], groupOptions: [], sumField: '' };
  var keyIdx = 0;          // groupOptions 인덱스
  var mode = 'GROUP';      // GROUP | DISTINCT
  var keysEl = document.querySelector('.gbl-keys');
  var modeEl = document.querySelector('.gbl-mode');
  var srcEl = document.getElementById('gblSrc');
  var resHost = document.getElementById('gblRes');
  var noteEl = document.getElementById('gblNote');

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }
  function curKeys() { return CFG.groupOptions[keyIdx].keys; }
  function keyOf(r) { return curKeys().map(function (k) { return r[k]; }).join(' · '); }

  // 그룹 순서(첫 등장순)와 인덱스
  function groupOrder() {
    var seen = {}, order = [];
    CFG.rows.forEach(function (r) { var k = keyOf(r); if (!(k in seen)) { seen[k] = order.length; order.push(k); } });
    return { seen: seen, order: order };
  }

  function renderSrc() {
    var go = groupOrder();
    var head = '<tr>' + CFG.cols.map(function (c) { return '<th>' + c.label + '</th>'; }).join('') + '</tr>';
    var body = CFG.rows.map(function (r) {
      var gi = go.seen[keyOf(r)] % 4;
      return '<tr class="g' + gi + '">' + CFG.cols.map(function (c) {
        return '<td class="' + (c.num ? 'num' : '') + '">' + esc(r[c.key]) + '</td>';
      }).join('') + '</tr>';
    }).join('');
    srcEl.innerHTML = head + body;
  }

  function aggregate() {
    var go = groupOrder(), groups = {};
    CFG.rows.forEach(function (r) {
      var k = keyOf(r);
      if (!groups[k]) groups[k] = { key: r, cnt: 0, sum: 0, max: -Infinity };
      groups[k].cnt++;
      var v = Number(r[CFG.sumField]) || 0;
      groups[k].sum += v; if (v > groups[k].max) groups[k].max = v;
    });
    return go.order.map(function (k) { return groups[k]; });
  }

  function renderResult() {
    if (mode === 'DISTINCT') {
      var go = groupOrder();
      var head = '<tr>' + curKeys().map(function (k) { return '<th>' + k + '</th>'; }).join('') + '</tr>';
      var body = go.order.map(function (k) {
        return '<tr>' + k.split(' · ').map(function (v) { return '<td>' + esc(v) + '</td>'; }).join('') + '</tr>';
      }).join('');
      resHost.innerHTML = '<table class="gbl-tbl gbl-res"><thead>' + head + '</thead><tbody>' + body + '</tbody></table>';
      noteEl.innerHTML = '<b>SELECT DISTINCT ' + curKeys().join(' ') + '</b> — 중복만 제거한 <b>' + go.order.length + '행</b>. 집계(건수·합계)는 없습니다.';
      return;
    }
    var aggs = aggregate();
    var sf = CFG.sumField;
    var head = '<tr>' + curKeys().map(function (k) { return '<th>' + k + '</th>'; }).join('') +
      '<th>COUNT(*)</th><th>SUM(' + sf + ')</th><th>MAX(' + sf + ')</th></tr>';
    var body = aggs.map(function (g) {
      var keyCells = curKeys().map(function (k) { return '<td>' + esc(g.key[k]) + '</td>'; }).join('');
      return '<tr>' + keyCells + '<td class="num">' + g.cnt + '</td><td class="num">' + g.sum + '</td><td class="num">' + g.max + '</td></tr>';
    }).join('');
    resHost.innerHTML = '<table class="gbl-tbl gbl-res"><thead>' + head + '</thead><tbody>' + body + '</tbody></table>';
    noteEl.innerHTML = '원본 <b>' + CFG.rows.length + '행</b> → <b>GROUP BY ' + curKeys().join(' ') + '</b> → <b>' + aggs.length + '행</b>으로 접힘. 그룹 키가 아닌 평컬럼(예: 고객)은 한 그룹에 여러 값이라 그대로 못 고릅니다.';
  }

  function renderSeg(host, items, activeI, attr) {
    host.innerHTML = items.map(function (it, i) {
      return '<button type="button" data-i="' + i + '" aria-pressed="' + (i === activeI ? 'true' : 'false') + '">' + esc(it) + '</button>';
    }).join('');
  }

  function render() {
    renderSeg(keysEl, CFG.groupOptions.map(function (o) { return o.label; }), keyIdx);
    renderSeg(modeEl, ['GROUP BY', 'DISTINCT'], mode === 'GROUP' ? 0 : 1);
    renderSrc(); renderResult();
  }

  keysEl.addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; keyIdx = +b.getAttribute('data-i'); render(); });
  modeEl.addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; mode = (+b.getAttribute('data-i') === 0) ? 'GROUP' : 'DISTINCT'; render(); });

  render();
})();

FILE: C:\SAP\sap-dev-academy\embeds\_engine\where-having-pipeline.js
/* where-having-pipeline 엔진 — 원본→WHERE→GROUP BY→HAVING 4단계를 한 단계씩 진행하며
   "WHERE는 행 하나, HAVING은 그룹 하나"를 보여 준다.
   골격 계약: [data-code] · .whp-stages · #whpData · #whpFb · [data-next] · [data-reset] · [data-progress].
   config: window.WHP_CFG = { rows:[..], rowCols:[{key,label,num}], code:[lines], hlMap:{where,group,having},
            whereField, whereOp('>='|'>'), whereVal, groupKey, havingVal,
            sumField, sumLabel, rowNoun, groupNoun }. 높이: _autoheight.js. */
(function () {
  var CFG = window.WHP_CFG || {};
  var ROWS = CFG.rows || [];
  var OP = CFG.whereOp || '>=';                     // WHERE 비교 연산자
  var FAILOP = OP === '>' ? '≤' : '&lt;';            // 탈락 행 태그에 쓸 반대 조건
  var SUMLB = CFG.sumLabel || ('SUM(' + (CFG.sumField || '') + ')');
  var ROWN = CFG.rowNoun || '행';
  var GRPN = CFG.groupNoun || '그룹';
  var KW = new Set('SELECT FROM INTO TABLE WHERE GROUP BY HAVING COUNT AS CORRESPONDING FIELDS OF'.split(' '));
  var STAGES = ['원본', 'WHERE 후', 'GROUP BY 후', 'HAVING 후'];
  var codeBox = document.querySelector('[data-code]');
  var stagesBox = document.querySelector('.whp-stages');
  var dataEl = document.getElementById('whpData');
  var fbEl = document.getElementById('whpFb');
  var nextBtn = document.querySelector('[data-next]');
  var resetBtn = document.querySelector('[data-reset]');
  var progEl = document.querySelector('[data-progress]');
  var stage = 0;

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }
  function hl(line) {
    if (/^\s*"/.test(line)) return '<span class="tok-com">' + esc(line) + '</span>';
    var out = '', re = /(\b\d+\b)|([A-Za-z_][A-Za-z0-9_*]*)|([^A-Za-z0-9_]+)/g, m;
    while ((m = re.exec(line)) !== null) {
      if (m[1]) out += '<span class="tok-num">' + esc(m[1]) + '</span>';
      else if (m[2]) out += KW.has(m[2].toUpperCase()) ? '<span class="tok-kw">' + esc(m[2]) + '</span>' : esc(m[2]);
      else out += esc(m[0]);
    }
    return out;
  }
  // 계산
  function passWhere(r) {
    var v = Number(r[CFG.whereField]);
    return OP === '>' ? v > CFG.whereVal : v >= CFG.whereVal;
  }
  function groups() {
    var g = {}, order = [];
    ROWS.filter(passWhere).forEach(function (r) {
      var k = r[CFG.groupKey];
      if (!g[k]) { g[k] = { key: k, cnt: 0, sum: 0 }; order.push(k); }
      g[k].cnt++; g[k].sum += Number(r[CFG.sumField]) || 0;
    });
    return order.map(function (k) { return g[k]; });
  }

  if (codeBox) codeBox.innerHTML = '<ol>' + CFG.code.map(function (l) { return '<li>' + (l ? hl(l) : '&nbsp;') + '</li>'; }).join('') + '</ol>';
  var lines = codeBox ? codeBox.querySelectorAll('li') : [];

  function renderStages() {
    stagesBox.innerHTML = STAGES.map(function (s, i) {
      var cls = i === stage ? 'on' : (i < stage ? 'done' : '');
      return '<div class="whp-stage ' + cls + '">' + (i + 1) + '. ' + s + '</div>';
    }).join('');
  }
  function hlCode() {
    var hlLine = -1;
    if (stage === 1) hlLine = CFG.hlMap.where;
    else if (stage === 2) hlLine = CFG.hlMap.group;
    else if (stage === 3) hlLine = CFG.hlMap.having;
    lines.forEach(function (li, i) { li.classList.toggle('on', i === hlLine); });
  }

  function renderData() {
    if (stage <= 1) {
      // 개별 행 (stage1이면 WHERE 실패 행 cut)
      var cols = CFG.rowCols || [];
      var head = '<tr>' + cols.map(function (c) { return '<th>' + esc(c.label || c.key) + '</th>'; }).join('') + '<th>판정</th></tr>';
      var body = ROWS.map(function (r) {
        var cut = stage === 1 && !passWhere(r);
        var tag = stage === 1
          ? (cut ? '<span class="whp-tag cut">제외(' + esc(CFG.whereField) + ' ' + FAILOP + ' ' + CFG.whereVal + ')</span>'
                 : '<span class="whp-tag keep">유지</span>')
          : '';
        var tds = cols.map(function (c) { return '<td class="' + (c.num ? 'num' : '') + '">' + esc(r[c.key]) + '</td>'; }).join('');
        return '<tr class="' + (cut ? 'cut' : '') + '">' + tds + '<td>' + tag + '</td></tr>';
      }).join('');
      dataEl.innerHTML = '<table class="whp-tbl"><thead>' + head + '</thead><tbody>' + body + '</tbody></table>';
    } else {
      // 그룹 행 (stage3이면 HAVING 실패 그룹 cut)
      var gs = groups();
      var head2 = '<tr><th>' + esc(CFG.groupKey) + '</th><th>COUNT(*)</th><th>' + esc(SUMLB) + '</th><th>판정</th></tr>';
      var body2 = gs.map(function (g) {
        var cut = stage === 3 && g.cnt < CFG.havingVal;
        var tag = stage === 3
          ? (cut ? '<span class="whp-tag cut">제외(cnt&lt;' + CFG.havingVal + ')</span>' : '<span class="whp-tag keep">유지</span>')
          : '';
        return '<tr class="' + (cut ? 'cut' : 'grp') + '"><td>' + esc(g.key) + '</td><td class="num">' + g.cnt + '</td><td class="num">' + g.sum + '</td><td>' + tag + '</td></tr>';
      }).join('');
      dataEl.innerHTML = '<table class="whp-tbl"><thead>' + head2 + '</thead><tbody>' + body2 + '</tbody></table>';
    }
  }

  var FB = [
    '원본 ' + ROWN + ' ' + ROWS.length + '행. ▶로 단계를 진행하세요.',
    'WHERE ' + CFG.whereField + ' ' + esc(OP) + ' ' + CFG.whereVal + ' — 개별 <b>행</b> 필터. 조건 미달 행이 빠집니다.',
    'GROUP BY ' + CFG.groupKey + ' — 남은 행을 ' + GRPN + '별로 묶어 COUNT·' + SUMLB + ' 계산.',
