if(id==='CH13-L05-S01'){x.orders=[]; const n=await p.locator('.spl-chip').count(); for(let i=0;i<n;i++){await p.locator('.spl-chip').nth(i).click(); x.orders.push(await p.locator('#splFb').innerText());}}
if(id==='CH13-L06-S01'){await p.locator('[data-run]').click(); x.normal=await p.locator('#faeStatus').innerText(); await p.locator('.fae-keys button').nth(1).click(); await p.locator('[data-run]').click(); x.safe=await p.locator('#faeStatus').innerText(); await p.locator('[data-safety]').click(); await p.locator('[data-run]').click(); x.danger=await p.locator('#faeStatus').innerText(); await p.locator('.fae-keys button').nth(2).click(); await p.locator('[data-run]').click(); x.dup=await p.locator('#faeStatus').innerText();}
if(id==='CH13-L07-S01'){const cards=p.locator('.card'); for(let i=0;i<await cards.count();i++) await cards.nth(i).locator('.cbtn').first().click(); x.score=await p.locator('#score').innerText(); x.feedback=await p.locator('.fb').allInnerTexts();}
if(id==='CH13-L08-S01'){x.left=await p.locator('#javRes').innerText(); await p.locator('[data-j=\"INNER\"]').click(); x.inner=await p.locator('#javRes').innerText(); x.code=await p.locator('#javCode').innerText();}
x.errors=errs.slice(); out.push(x); await p.close();}
await b.close(); console.log(JSON.stringify(out));})().catch(e=>{console.error(e);process.exit(1)});
'@; node -e "'$js'

